dossiers.argument_source:
language "EAL/2";
environment dosing_rig {
  require "rig" == "DX-14";
  require "run" == "S6";
}
tool flow_reader { version "1"; mode deterministic; }
tool certificate_reader { version "1"; mode deterministic; }
tool drift_reader { version "1"; mode deterministic; }
tool crosscheck_reader { version "1"; mode deterministic; }
evidence flow_record {
  tool flow_reader; kind test; environment dosing_rig; max_age 3600;
  require "run" == "S6";
  require "max_error_pct" <= 2;
}
evidence calibration_certificate {
  tool certificate_reader; kind validation; environment dosing_rig; max_age 3600;
  require "rig" == "DX-14";
  require "calibration_id" == "C-88";
  require "passed" == true;
}
evidence drift_alert {
  tool drift_reader; kind inspection; environment dosing_rig; max_age 3600;
  require "rig" == "DX-14";
  require "finding" == "offset_drift";
}
evidence independent_crosscheck {
  tool crosscheck_reader; kind independent_check; environment dosing_rig; max_age 3600;
  require "rig" == "DX-14";
  require "finding" == "separate_reference_agrees";
}
assumption reference_current {
  statement "The C-88 reference characterisation applies to DX-14 during run S6.";
  environment dosing_rig;
  validate calibration_certificate;
  valid_from "2026-09-24T11:00:00Z";
  valid_until "2026-09-24T13:00:00Z";
}
reasoning recorded_error {
  method "structured/1";
  rationale "The reported error qualifies the limited bench conclusion only while the separately validated reference assumption can be used. Independent crosscheck can answer the drift alert but does not authenticate the device.";
}
claim bounded_dosing_error {
  statement "For DX-14 run S6, the reported dosing error is no greater than two percent under its applicable C-88 reference characterisation.";
  environment dosing_rig;
}
argument flow_route {
  conclusion bounded_dosing_error;
  reasoning recorded_error; evidence flow_record; assumptions reference_current;
}
objection reference_drift { target assumption reference_current; evidence drift_alert; }
objection separate_reference { target objection reference_drift; evidence independent_crosscheck; }

language "EAL/2";
environment thermal_run {
  require "rig" == "TC-9";
  require "run" == "H4";
}
tool soak_reader { version "1"; mode deterministic; }
evidence qualifying_log {
  tool soak_reader; kind test; environment thermal_run; max_age 900;
  require "rig" == "TC-9";
  require "run" == "H4";
  require "sensor" == "K2";
  require "calibration_valid" == true;
  require "peak_c" <= 82;
  require "dwell_min" >= 30;
}
reasoning threshold_record {
  method "structured/1";
  rationale "The current submitted H4 log must report all stated thermal and sensor conditions. This only describes that record; it does not independently validate a physical soak cycle or calibration.";
}
claim soak_preconditions {
  statement "A TC-9 H4 log acquired within 15 minutes reports valid K2 calibration, a peak no greater than 82 C and dwell of at least 30 minutes.";
  environment thermal_run;
}
argument logged_run { conclusion soak_preconditions; reasoning threshold_record; evidence qualifying_log; }

language "EAL/2";
environment failover_run {
  require "switch" == "NS-9";
  require "profile" == "dual_uplink_A";
}
tool failover_reader { version "1"; mode deterministic; }
tool buffer_alert_reader { version "1"; mode deterministic; }
tool packet_trace_reader { version "1"; mode deterministic; }
evidence loaded_failover {
  tool failover_reader; kind test; environment failover_run; max_age 1800;
  require "switch" == "NS-9";
  require "profile" == "dual_uplink_A";
  require "switchover_ms" <= 250;
  require "load_pct" >= 70;
  require "pass" == true;
}
evidence buffer_alert {
  tool buffer_alert_reader; kind monitoring; environment failover_run; max_age 1800;
  require "switch" == "NS-9";
  require "finding" == "switch_buffer_overrun";
}
evidence independent_trace {
  tool packet_trace_reader; kind independent_check; environment failover_run; max_age 1800;
  require "switch" == "NS-9";
  require "profile" == "dual_uplink_A";
  require "finding" == "alert_from_test_generator";
}
reasoning failover_record {
  method "structured/1";
  rationale "The current loaded-failover test supports only the reported bounded switch result. A matching buffer alert challenges its interpretation; a separate packet trace explicitly attributing that alert to the generator answers that specific challenge, subject to review of the trace's provenance.";
}
claim bounded_failover {
  statement "For the NS-9 dual-uplink-A loaded test, the submitted record reports successful switchover within 250 ms at at least 70 percent load.";
  environment failover_run;
}
argument loaded_route { conclusion bounded_failover; reasoning failover_record; evidence loaded_failover; }
objection buffer_challenge { target argument loaded_route; evidence buffer_alert; }
objection separate_trace { target objection buffer_challenge; evidence independent_trace; }

language "EAL/2";
environment staged_release {
  require "release" == "PX-42";
  require "lane" == "West-2";
}
tool build_reader { version "1"; mode deterministic; }
tool stage_reader { version "1"; mode deterministic; }
evidence signed_build_record {
  tool build_reader; kind provenance; environment staged_release; max_age 3600;
  require "release" == "PX-42";
  require "revision" == "b64";
  require "digest" == "sha256:8c4a";
  require "signature_verified" == true;
}
evidence staged_pull_record {
  tool stage_reader; kind deployment_record; environment staged_release; max_age 3600;
  require "release" == "PX-42";
  require "lane" == "West-2";
  require "digest" == "sha256:8c4a";
  require "pull_verified" == true;
}
reasoning record_identity {
  method "structured/1";
  rationale "A current attestation and staged-pull record naming the same pinned digest establish identity of the submitted records under the stated verification flags. These synthetic flags do not authenticate a real signature or deployed byte stream.";
}
claim build_qualifies {
  statement "The submitted PX-42 b64 build record names the pinned digest and reports signature verification.";
  environment staged_release;
}
claim stage_qualifies {
  statement "The submitted West-2 staged-pull record for PX-42 names the pinned digest and reports verification.";
  environment staged_release;
}
claim stage_matches_build {
  statement "The current signed-build and West-2 staged-pull records both identify the pinned PX-42 b64 digest sha256:8c4a.";
  environment staged_release;
}
argument build_route { conclusion build_qualifies; reasoning record_identity; evidence signed_build_record; }
argument stage_route { conclusion stage_qualifies; reasoning record_identity; evidence staged_pull_record; }
argument identity_route {
  conclusion stage_matches_build; reasoning record_identity;
  premises build_qualifies, stage_qualifies;
}

language "EAL/2";
environment fan_rig {
  require "facility" == "North-1";
  require "unit" == "AH-73";
}
tool probe_reader { version "1"; mode deterministic; }
tool alignment_reader { version "1"; mode deterministic; }
evidence direction_record {
  tool probe_reader; kind test; environment fan_rig; max_age 3600;
  require "unit" == "AH-73";
  require "drive_firmware" == "r17";
  require "programme" == "warm_restart";
  require "direction" == "forward";
  require "pass" == true;
}
evidence alignment_notice {
  tool alignment_reader; kind inspection; environment fan_rig; max_age 3600;
  require "unit" == "AH-73";
  require "finding" == "fixture_misalignment";
}
reasoning bench_relation {
  method "structured/1";
  rationale "A passing, correctly identified bench record is an authored ground for the recorded direction claim. The source does not authenticate the physical actuator.";
}
claim recorded_direction {
  statement "Within the North-1 bench fixture and declared procedure, the AH-73 r17 warm-restart test demonstrated forward shaft direction.";
  environment fan_rig;
}
argument matching_test {
  conclusion recorded_direction; reasoning bench_relation; evidence direction_record;
}
objection suspect_fixture {
  target argument matching_test; evidence alignment_notice;
}

language "EAL/2";
environment loop_run {
  require "loop" == "HL-5";
  require "run" == "Q17";
}
tool step_reader { version "1"; mode deterministic; }
tool reference_reader { version "1"; mode deterministic; }
tool wiring_reader { version "1"; mode deterministic; }
evidence step_record {
  tool step_reader; kind test; environment loop_run; max_age 3600;
  require "run" == "Q17";
  require "settling_ms" <= 120;
}
evidence flow_reference {
  tool reference_reader; kind calibration; environment loop_run; max_age 3600;
  require "run" == "Q17";
  require "reference_id" == "REF-31";
  require "calibrated" == true;
}
evidence wiring_clearance {
  tool wiring_reader; kind inspection; environment loop_run; max_age 3600;
  require "run" == "Q17";
  require "finding" == "no_reversal_observed";
  require "checked_connectors" == 4;
  require "inspection_complete" == true;
  require "positions.J1" == "clear";
  require "positions.J2" == "clear";
  require "positions.J3" == "clear";
  require "positions.J4" == "clear";
}
reasoning direct_record { method "structured/1"; rationale "Each record supplies only its own stated bench precondition."; }
reasoning conjunction { method "structured/1"; rationale "The provisional continuation decision requires the step and reference records plus a reported negative inspection of each of J1, J2, J3 and J4. A count or completion flag alone cannot establish distinct-position coverage; neither can these self-reported fields authenticate the physical inspection."; }
claim step_qualifies {
  statement "The HL-5 run Q17 bench record reports settlement within 120 ms.";
  environment loop_run;
}
claim reference_qualifies {
  statement "The HL-5 run Q17 flow reference is documented as calibrated against REF-31 in a current record.";
  environment loop_run;
}
claim wiring_qualifies {
  statement "The completed Q17 inspection record reports no reversed pair at each of J1, J2, J3 and J4.";
  environment loop_run;
}
claim continuation_preconditions {
  statement "For HL-5 run Q17, the recorded step, flow-reference and bounded connector-inspection preconditions jointly hold for the provisional continuation decision.";
  environment loop_run;
}
argument step_route { conclusion step_qualifies; reasoning direct_record; evidence step_record; }
argument reference_route { conclusion reference_qualifies; reasoning direct_record; evidence flow_reference; }
argument wiring_route { conclusion wiring_qualifies; reasoning direct_record; evidence wiring_clearance; }
argument combined_route {
  conclusion continuation_preconditions; reasoning conjunction;
  premises step_qualifies, reference_qualifies, wiring_qualifies;
}

language "EAL/2";
environment controller {
  require "fixture" == "vent-controller-6";
  require "recipe" == "R5";
}
tool model_reader { version "1"; mode deterministic; }
evidence affine_model {
  tool model_reader; kind causal_model; environment controller; max_age 3600;
  require "intervention.variable" == "valve_drive";
  require "intervention.value" == 5;
  require "outcome" == "vent_load";
}
reasoning bounded_intervention {
  method "counterfactual/1";
  rationale "Compute the vent-load index for an intervention setting valve_drive to five within each supplied acyclic affine model, retaining that model's stated noise values. The supplied model is not physically validated here.";
  require "counterfactual" <= 8;
}
claim intervention_within_limit {
  statement "Under the supplied affine vent-controller model and its fixed exogenous values, setting valve_drive to five gives a vent-load index no greater than eight.";
  environment controller;
}
argument model_calculation {
  conclusion intervention_within_limit; reasoning bounded_intervention; evidence affine_model;
}

